#!/bin/bash
# NOVA wrapper: Asterisk reads its configuration from /nova-conf (mounted read-only; generated by
# NOVA from the telephony settings). Changes are copied into /etc/asterisk every few seconds and
# Asterisk is reloaded, so no restart is needed after adding an extension.
set -euo pipefail

CONF_SRC=/nova-conf
CONF_DST=/etc/asterisk
FILES=(pjsip.conf extensions.conf ari.conf http.conf rtp.conf manager.conf modules.conf)

if [ ! -f "$CONF_SRC/pjsip.conf" ]; then
  echo "NOVA: geen configuratie gevonden in $CONF_SRC." >&2
  echo "NOVA: zet Telefonie aan in NOVA (Instellingen > Telefonie) en start deze container opnieuw." >&2
  exit 1
fi

install_conf() {
  for f in "${FILES[@]}"; do
    [ -f "$CONF_SRC/$f" ] && install -m 0640 -o asterisk -g asterisk "$CONF_SRC/$f" "$CONF_DST/$f"
  done
  mkdir -p /var/spool/asterisk/recording/nova
  chown asterisk:asterisk /var/spool/asterisk/recording/nova 2>/dev/null || true
}

fingerprint() {
  cat "$CONF_SRC"/*.conf 2>/dev/null | sha256sum | cut -d' ' -f1
}

install_conf
last="$(fingerprint)"

(
  while sleep 5; do
    now="$(fingerprint)"
    if [ "$now" != "$last" ]; then
      install_conf
      asterisk -rx "core reload" >/dev/null 2>&1 && last="$now"
    fi
  done
) &

exec /usr/local/bin/entrypoint.sh "$@"
